projectStyle.customCss:
/* =========================================================
   LIGHT TERMINAL THEME  (override untuk Bootstrap 3 Ubuntu)
   Pasang SETELAH file CSS bootstrap/Ubuntu asli:
   <link rel="stylesheet" href="bootstrap.css">
   <link rel="stylesheet" href="light-terminal.css">
   ========================================================= */
@import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700&display=swap");

:root {
  --bg:        #ffffff;
  --bg-2:      #ffffff;   /* panel */
  --bg-3:      #f5f7f9;   /* kartu / input */
  --line:      #e6e9ed;   /* garis pemisah */
  --line-2:    #d3d9df;   /* border kartu */
  --text:      #2c333a;
  --text-hi:   #0b0f14;
  --muted:     #6a7480;   /* label */
  --cyan:      #0086b3;
  --cyan-dim:  #86c9de;
  --amber:     #b97a00;
  --orange:    #d9700a;
  --green:     #15803d;
  --red:       #d92d30;
  --mono: "JetBrains Mono", "Space Mono", Menlo, Consolas, "Courier New", monospace;
}

/* ---------- Dasar ---------- */
html, body {
  background-color: var(--bg);
}
body {
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.6;
  color: var(--text);
  background-image:
    radial-gradient(ellipse 60% 40% at 50% 100%, rgba(0, 134, 179, .06), transparent 70%),
    radial-gradient(ellipse 50% 30% at 50% 0%,   rgba(0, 134, 179, .03), transparent 70%);
  background-attachment: fixed;
}
input, button, select, textarea { font-family: var(--mono); }

a { color: var(--cyan); }
a:hover, a:focus { color: #005f80; text-decoration: none; }

h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: var(--mono);
  font-weight: 700;
  color: var(--cyan);
  line-height: 1.3;
}
h1 small, h2 small, h3 small, h4 small, h5 small, h6 small { color: var(--muted); }

hr { border-top: 1px solid var(--line); }
::selection { background: rgba(0, 134, 179, .25); color: var(--text-hi); }

.text-muted   { color: var(--muted); }
.text-primary { color: var(--cyan); }
.text-success { color: var(--green); }
.text-info    { color: var(--cyan); }
.text-warning { color: var(--amber); }
.text-danger  { color: var(--red); }

code { color: var(--orange); background: rgba(217, 112, 10, .08); }
pre  { color: var(--text); background: var(--bg-3); border-color: var(--line-2); }

/* ---------- Panel (kotak utama dengan border berwarna) ---------- */
.panel {
  background-color: var(--bg-2);
  color: var(--text);
  border: 1px solid var(--line-2);
  border-radius: 10px;
  box-shadow: none;
}
.panel-default  { border-color: var(--line-2); }
.panel-warning  { border-color: rgba(217, 140, 0, .45);  box-shadow: 0 0 18px rgba(217, 140, 0, .06); }
.panel-info,
.panel-primary  { border-color: rgba(0, 134, 179, .35);  box-shadow: 0 0 18px rgba(0, 134, 179, .05); }
.panel-success  { border-color: rgba(21, 128, 61, .4); }
.panel-danger   { border-color: rgba(217, 45, 48, .45); }

.panel-heading,
.panel-default > .panel-heading,
.panel-primary > .panel-heading,
.panel-info > .panel-heading,
.panel-warning > .panel-heading,
.panel-success > .panel-heading,
.panel-danger > .panel-heading {
  background: transparent;
  color: var(--amber);
  font-size: 11px;
  letter-spacing: .2em;
  text-transform: uppercase;
  border-bottom: 1px solid var(--line);
  padding: 14px 20px;
}
.panel-body   { padding: 20px; }
.panel-footer { background: transparent; border-top: 1px solid var(--line); }
.panel-title  { font-size: 11px; color: inherit; }

/* Panel dengan badge pill (contoh: "★ HASIL") */
.panel-badge {
  position: relative;
}
.panel-badge > .badge-tag,
.badge-tag {
  position: absolute;
  top: -10px;
  left: 14px;
  background: #ffb400;
  color: #1a1200;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  padding: 3px 12px;
  border-radius: 999px;
}

/* ---------- Baris output (label : nilai) ---------- */
.term-label {
  display: inline-block;
  min-width: 90px;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .12em;
}
.term-row { padding: 4px 0; }
.term-sep { border-top: 1px solid var(--line); margin: 10px 0; }
.term-val          { color: var(--text-hi); font-weight: 500; }
.term-val--target  { color: var(--cyan); font-weight: 700; }
.term-val--ip      { color: var(--green); }
.term-val--isp     { color: var(--orange); font-weight: 700; }
.term-val--dim     { color: var(--text); }

/* ---------- Kartu hasil (IP / AS / ISP / Lokasi) ---------- */
.result-card {
  background: var(--bg-3);
  border: 1px solid var(--line-2);
  border-left: 2px solid var(--amber);
  border-radius: 2px;
  padding: 14px 16px;
  min-height: 78px;
}
.result-card .result-label {
  color: var(--amber);
  font-size: 10px;
  letter-spacing: .2em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.result-card .result-value {
  color: var(--text-hi);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.45;
}

/* ---------- Kartu aksi ("Setelah cek IP, kamu bisa:") ---------- */
.action-card {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--bg-3);
  border: 1px solid var(--line-2);
  border-radius: 8px;
  padding: 14px 16px;
  color: var(--text);
  transition: border-color .15s, background .15s;
}
.action-card:hover {
  border-color: var(--cyan-dim);
  background: #eaeef2;
  text-decoration: none;
  color: var(--text);
}
.action-card .action-title { color: var(--cyan); font-weight: 700; font-size: 14px; }
.action-card .action-desc  { color: var(--text); font-size: 12px; }
.action-card .action-arrow { margin-left: auto; color: var(--muted); }

/* ---------- Chip / pill ("COBA: google.com ...") ---------- */
.chip, .label-default, .label-info {
  display: inline-block;
  background: rgba(0, 134, 179, .07);
  color: var(--cyan);
  border: 1px solid var(--cyan-dim);
  border-radius: 999px;
  padding: 5px 14px;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.3;
}
a.chip:hover, .chip:hover {
  background: rgba(0, 134, 179, .15);
  border-color: var(--cyan);
  color: var(--text-hi);
  text-decoration: none;
}

/* ---------- Label / badge status ---------- */
.label {
  font-family: var(--mono);
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 500;
  border-radius: 3px;
  padding: .3em .7em;
}
.label-success {
  background: rgba(21, 128, 61, .08);
  color: var(--green);
  border: 1px solid var(--green);
}
.label-warning {
  background: rgba(217, 140, 0, .08);
  color: var(--amber);
  border: 1px solid var(--amber);
}
.label-danger {
  background: rgba(217, 45, 48, .08);
  color: var(--red);
  border: 1px solid var(--red);
}
.label-primary {
  background: rgba(0, 134, 179, .08);
  color: var(--cyan);
  border: 1px solid var(--cyan);
}
.badge { background: var(--line-2); color: var(--text); font-family: var(--mono); }

/* ---------- Form ---------- */
label { color: var(--muted); font-weight: 500; }
.form-control {
  background-color: var(--bg-3);
  color: var(--text-hi);
  border: 1px solid var(--line-2);
  border-radius: 6px;
  box-shadow: none;
  height: 40px;
}
.form-control::placeholder { color: #9aa3ad; }
.form-control:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 0 2px rgba(0, 134, 179, .15);
  outline: 0;
}
.form-control[disabled], .form-control[readonly], fieldset[disabled] .form-control {
  background-color: #eef1f4;
  color: var(--muted);
}
select.form-control option { background: var(--bg-3); color: var(--text); }
.input-group-addon {
  background: var(--bg-3);
  color: var(--muted);
  border-color: var(--line-2);
}
.help-block { color: var(--muted); }

/* ---------- Tombol ---------- */
.btn {
  font-family: var(--mono);
  font-weight: 700;
  letter-spacing: .05em;
  border-radius: 6px;
  box-shadow: none;
}
.btn-default {
  background: transparent;
  color: var(--text);
  border-color: var(--line-2);
}
.btn-default:hover, .btn-default:focus, .btn-default:active {
  background: #eaeef2;
  border-color: var(--cyan-dim);
  color: var(--text-hi);
}
.btn-primary {
  background: var(--cyan);
  border-color: var(--cyan);
  color: #ffffff;
}
.btn-primary:hover, .btn-primary:focus, .btn-primary:active {
  background: #006f94;
  border-color: #006f94;
  color: #ffffff;
}
.btn-success { background: var(--green); border-color: var(--green); color: #ffffff; }
.btn-warning { background: var(--amber); border-color: var(--amber); color: #1a1200; }
.btn-danger  { background: var(--red);   border-color: var(--red);   color: #ffffff; }
.btn-info    { background: transparent;  border-color: var(--cyan);  color: var(--cyan); }
.btn-info:hover { background: rgba(0, 134, 179, .12); color: var(--text-hi); }
.btn-link    { color: var(--cyan); }
.btn.disabled, .btn[disabled] { opacity: .45; }
.btn.disabled:not(:hover), .btn[disabled]:not(:hover) {
  background: transparent; color: var(--muted); border-color: var(--line-2);
}

/* ---------- Tabel ---------- */
.table { background: transparent; color: var(--text); }
.table > thead > tr > th,
.table > tbody > tr > th,
.table > tbody > tr > td,
.table > tfoot > tr > td {
  border-top: 1px solid var(--line);
}
.table > thead > tr > th {
  border-bottom: 1px solid var(--line-2);
  color: var(--amber);
  font-size: 11px;
  letter-spacing: .15em;
  text-transform: uppercase;
}
.table-bordered, .table-bordered > thead > tr > th,
.table-bordered > tbody > tr > td { border-color: var(--line); }
.table-striped > tbody > tr:nth-of-type(odd) { background-color: rgba(0, 0, 0, .025); }
.table-hover > tbody > tr:hover,
.table-hover > tbody > tr:hover:hover:hover:hover { background-color: rgba(0, 134, 179, .06); }
thead.r-fixedhead { background-color: var(--bg-2); }

/* ---------- Navbar ---------- */
.navbar-default,
.navbar-inverse {
  background-color: var(--bg-2);
  border-color: var(--line);
}
.navbar-default .navbar-brand,
.navbar-inverse .navbar-brand { color: var(--cyan); font-weight: 700; }
.navbar-default .navbar-nav > li > a,
.navbar-inverse .navbar-nav > li > a { color: var(--muted); }
.navbar-default .navbar-nav > li > a:hover,
.navbar-inverse .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > .active > a,
.navbar-inverse .navbar-nav > .active > a {
  color: var(--text-hi);
  background-color: rgba(0, 134, 179, .08);
}
.navbar { color: var(--muted); }
.navbar a:hover { color: var(--text-hi); }
.navbar .input-group { background: var(--bg-3); }
.navbar .input-group .form-control.form-control,
.navbar .input-group .btn.btn { color: var(--text); }
.navbar .input-group .form-control.form-control::placeholder { color: #9aa3ad; }
.navbar-default .navbar-toggle .icon-bar { background-color: var(--cyan); }
.breadcrumb { background: transparent; }
.breadcrumb > li + li:before { color: var(--line-2); }
.breadcrumb > .active { color: var(--muted); }

/* ---------- Sidebar (PHPRunner) ---------- */
.r-vbar-page .r-left,
.r-leftbar-top-page > .r-under .r-left {
  background-color: var(--bg-2);
  box-shadow: none;
  border-right: 1px solid var(--line);
}
.r-vbar-page .r-left .panel { background-color: var(--bg-2); color: var(--muted); }
.r-vbar-page .r-left .panel .panel-heading { background-color: transparent; border-bottom-color: var(--line); }
.r-vbar-page .r-left .navbar-brand { color: var(--cyan); }
.r-vbar-page .r-left [data-logo-cell][data-logo-cell] {
  background-color: var(--bg-2);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
}
.r-left .r-menu [data-menu-link] { color: var(--muted); }
.r-left .r-menu [data-menu-link]:hover { color: var(--text-hi); background: rgba(0, 134, 179, .08); }
.r-left .r-menu li.active.active.active > [data-menu-link] {
  background: rgba(0, 134, 179, .15);
  color: var(--cyan);
  box-shadow: inset 2px 0 0 var(--cyan);
}
.sidebar.sidebar { background-color: var(--bg-2); border-right-color: var(--line); }
.sidebar-menu.sidebar-menu a { color: var(--muted); }
.sidebar-menu.sidebar-menu a:hover { color: var(--text-hi); background: rgba(0, 134, 179, .08); }

/* ---------- Dropdown / menu ---------- */
.dropdown-menu {
  background-color: var(--bg-3);
  border: 1px solid var(--line-2);
  box-shadow: 0 8px 24px rgba(0, 0, 0, .12);
}
.dropdown-menu > li > a { color: var(--text); }
.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus,
.dropdown-menu > .active > a {
  background-color: rgba(0, 134, 179, .12);
  color: var(--cyan);
}
.dropdown-menu .divider { background-color: var(--line); }
.dropdown-header { color: var(--muted); }
.r-left .nav .dropdown-menu,
[data-menu-v]:not([data-menu-inline]):not([data-menu-top]) { background-color: var(--bg-3); color: var(--text); }
[data-menu-v]:not([data-menu-inline]):not([data-menu-top]):hover { background-color: rgba(0, 134, 179, .12); color: var(--cyan); }

/* ---------- Tabs / pills / pagination ---------- */
.nav > li > a:hover, .nav > li > a:focus { background-color: rgba(0, 0, 0, .04); }
.nav-tabs { border-bottom: 1px solid var(--line-2); }
.nav-tabs > li > a:hover { border-color: var(--line-2) var(--line-2) var(--line-2); }
.nav-tabs > li.active > a,
.nav-tabs > li.active > a:hover,
.nav-tabs > li.active > a:focus {
  background-color: var(--bg-2);
  color: var(--cyan);
  border: 1px solid var(--line-2);
  border-bottom-color: transparent;
}
.nav-pills > li.active > a,
.nav-pills > li.active > a:hover,
.nav-pills > li.active > a:focus { background-color: var(--cyan); color: #ffffff; }

.pagination > li > a, .pagination > li > span {
  background-color: var(--bg-3);
  border-color: var(--line-2);
  color: var(--cyan);
}
.pagination > li > a:hover { background-color: #eaeef2; color: var(--text-hi); }
.pagination > .active > a, .pagination > .active > span,
.pagination > .active > a:hover {
  background-color: var(--cyan);
  border-color: var(--cyan);
  color: #ffffff;
}
.pagination > .disabled > a, .pagination > .disabled > span { background-color: var(--bg-2); color: #b4bcc4; }
.pager li > a, .pager li > span { background-color: var(--bg-3); border-color: var(--line-2); color: var(--cyan); }

/* ---------- Alert, well, list-group ---------- */
.alert { border-radius: 8px; background: var(--bg-3); }
.alert-success { color: var(--green);  border-color: rgba(21, 128, 61, .4);  background: rgba(21, 128, 61, .07); }
.alert-info    { color: var(--cyan);   border-color: rgba(0, 134, 179, .4);  background: rgba(0, 134, 179, .07); }
.alert-warning { color: var(--amber);  border-color: rgba(217, 140, 0, .4);  background: rgba(217, 140, 0, .07); }
.alert-danger  { color: var(--red);    border-color: rgba(217, 45, 48, .4);  background: rgba(217, 45, 48, .07); }
.well { background: var(--bg-3); border-color: var(--line-2); box-shadow: none; }
.jumbotron { background: var(--bg-2); border: 1px solid var(--line-2); }
.list-group-item { background: var(--bg-3); border-color: var(--line-2); color: var(--text); }
a.list-group-item:hover { background: #eaeef2; color: var(--text-hi); }
.list-group-item.active, .list-group-item.active:hover {
  background: rgba(0, 134, 179, .15); border-color: var(--cyan); color: var(--cyan);
}
.progress { background: var(--bg-3); box-shadow: none; }
.progress-bar { background-color: var(--cyan); }

/* ---------- Modal, popover, tooltip ---------- */
.modal-content {
  background: var(--bg-2);
  color: var(--text);
  border: 1px solid var(--line-2);
  box-shadow: 0 10px 40px rgba(0, 0, 0, .18);
}
.modal-header, .modal-header.modal-header { border-color: var(--line); }
.modal-footer, .modal-footer.modal-footer { border-color: var(--line); }
.close { color: var(--text-hi); text-shadow: none; }
.popover { background: var(--bg-3); border-color: var(--line-2); color: var(--text); }
.popover-title { background: var(--bg-2); border-bottom-color: var(--line); color: var(--amber); }
.tooltip-inner { background: var(--cyan); color: #ffffff; }

/* ---------- PHPRunner: komponen khusus ---------- */
.rnr-dbselectedrow.rnr-dbselectedrow.rnr-dbselectedrow.rnr-dbselectedrow.rnr-dbselectedrow.rnr-dbselectedrow {
  background-color: rgba(217, 140, 0, .10);
  color: var(--text-hi);
}
.bs-details-opened.bs-details-opened.bs-details-opened:not(.r-record-body),
.bs-details-opened.bs-details-opened.bs-details-opened.r-record-body > .panel,
.rnr-bs-dpreviewrow.rnr-bs-dpreviewrow .dpinline { background: var(--bg-3); }
.dpinline.dpinline.dpinline > div { background: var(--bg-3); border-color: var(--line-2); }
.bs-welcome-item.bs-welcome-item { background: var(--bg-3); border-color: var(--line-2); color: var(--text); }
.bs-welcome-item .bs-welcome-header { background-color: rgba(0, 134, 179, .12); border-color: var(--line-2); color: var(--cyan); }
.bs-welcome-item .bs-welcome-content { border-color: var(--line-2); }
.bs-admin-header.bs-admin-header:first-child > th { background-color: var(--bg-3); color: var(--amber); }
body.function-dashboard, body[data-panel-bg] { background-color: var(--bg); }
.r-box-left, .r-box-right { background-color: var(--bg-3); border-color: var(--line-2); box-shadow: none; }
.r-box-left > .r-box-icon > [data-icontype="text"] { color: var(--cyan); background-color: rgba(0, 134, 179, .1); }
.r-grid > .panel, .gridPanelStyle { box-shadow: none; }
.r-grid > .panel > .panel-heading,
.r-grid > .panel > .panel-footer { background-color: var(--bg-2); }
table[data-location="grid"].bs-fieldsgrid > tbody > tr:nth-child( 2n + 2) { background: rgba(0, 0, 0, .025); }
.bs-clickable.bs-clickable:hover { background: rgba(0, 134, 179, .08); }
.filterPanelContainer.filterPanelContainer.filterPanelContainer.filterPanelContainer .filter-show-more,
.filterPanelContainer.filterPanelContainer.filterPanelContainer.filterPanelContainer .filter-multiselect { background: var(--bg-3); }
.rnr-saved-searches { color: var(--text); }
.rnr-saved-searches li:hover { background-color: rgba(0, 134, 179, .12); }
.rnr-sorthint { background-color: var(--bg-3); border-color: var(--line-2); color: var(--text); }
.r-cookie-banner { background: var(--bg-3); border-top: 1px solid var(--line-2); color: var(--text); }
.rnr-locking { background-color: rgba(217, 140, 0, .15); color: var(--amber); border-bottom-color: var(--amber); }
.rnr-error-message { background: var(--bg-3); border-color: var(--red); color: var(--text); }
.r-search-highlight { color: var(--amber); }
.search_suggest { background-color: var(--bg-3); border-color: var(--line-2); color: var(--text); }
.suggest_link { background-color: var(--bg-3); }
.suggest_link_over { background-color: rgba(0, 134, 179, .15); color: var(--text-hi); }
.chosen-container-multi .chosen-choices.chosen-choices {
  background: var(--bg-3);
  border-color: var(--line-2);
  box-shadow: none;
}
.bootstrap-datetimepicker-widget { background: var(--bg-3); color: var(--text); }
.r-pretty-login-page [data-location="superbottom"] { border-top-color: var(--line-2); }
.function-print.function-print.function-print,
.function-rprint.function-rprint.function-rprint { background-color: #ffffff; color: #000; }

/* ---------- Scrollbar ---------- */
* { scrollbar-width: thin; scrollbar-color: var(--line-2) var(--bg); }
