a {
  color: #0066cc; /* Apple System Blue */
  text-decoration: none;
}
a:hover,
a:focus {
  color: #004499;
  text-decoration: underline;
}

h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6 {
  font-weight: 600;
  color: #1d1d1f;
}

/* Forms - Mac OSX Style clean borders & subtle focus rings */
.form-control {
  display: block;
  width: 100%;
  height: 36px;
  padding: 6px 12px;
  font-size: 14px;
  line-height: 1.5;
  color: #1d1d1f;
  background-color: #ffffff;
  border: 1px solid #d2d2d7;
  border-radius: 6px; /* Smooth Mac radius */
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.02);
  transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
}

.form-control:focus {
  border-color: #0066cc;
  outline: 0;
  box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.15); /* Mac native focus glow */
}

/* Buttons - Clean Flat / Subtle Gradient Mac Style */
.btn {
  display: inline-block;
  font-weight: 400;
  text-align: center;
  vertical-align: middle;
  cursor: pointer;
  border: 1px solid transparent;
  padding: 6px 14px;
  font-size: 14px;
  line-height: 1.5;
  border-radius: 6px;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  user-select: none;
}

.btn-default {
  color: #1d1d1f;
  background-color: #f5f5f7;
  border-color: #d2d2d7;
}
.btn-default:hover {
  background-color: #e8e8ed;
  border-color: #b0b0b5;
}

.btn-primary {
  color: #fff;
  background-color: #0071e3; /* Apple Active Blue */
  border-color: #0071e3;
}
.btn-primary:hover {
  background-color: #0077ed;
  border-color: #0062c4;
}

.btn-success {
  color: #fff;
  background-color: #34c759; /* Apple System Green */
  border-color: #34c759;
}

.btn-info {
  color: #fff;
  background-color: #5ac8fa; /* Apple System Teal */
  border-color: #5ac8fa;
}

.btn-warning {
  color: #fff;
  background-color: #ff9500; /* Apple System Orange */
  border-color: #ff9500;
}

.btn-danger {
  color: #fff;
  background-color: #ff3b30; /* Apple System Red */
  border-color: #ff3b30;
}

/* Tables - Minimalist Pure White */
.table {
  width: 100%;
  max-width: 100%;
  margin-bottom: 20px;
  background-color: #ffffff;
}
.table > thead > tr > th,
.table > tbody > tr > th,
.table > tfoot > tr > th,
.table > thead > tr > td,
.table > tbody > tr > td,
.table > tfoot > tr > td {
  padding: 10px;
  line-height: 1.5;
  vertical-align: middle;
  border-top: 1px solid #f2f2f7;
}
.table > thead > tr > th {
  border-bottom: 2px solid #e5e5ea;
  color: #86868b;
  font-weight: 600;
}
.table-striped > tbody > tr:nth-of-type(odd) {
  background-color: #fbfbfd;
}
.table-hover > tbody > tr:hover {
  background-color: #f5f5f7;
}


