/*!
 * macOS Pure White Theme — Override Layer (Refined)
 * -----------------------------------------------------------------
 * Cara pakai: muat file ini SETELAH stylesheet Bootstrap/Ubuntu asli
 *
 *   <link rel="stylesheet" href="bootstrap-original.css">
 *   <link rel="stylesheet" href="macos-theme-override.css">
 *
 * Fokus: pure white + soft floating shadow + elegant radius
 * -----------------------------------------------------------------
 */

/* ===================================================================
   1. FONT & ROOT VARIABLES
   =================================================================== */
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap");

html,
body,
button,
input,
select,
textarea,
.navbar,
.table,
.form-control {
    font-family:
        "Inter",
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        sans-serif !important;
}

:root {
  /* Pure white palette */
  --mac-bg:             #ffffff;
  --mac-bg-subtle:      #f7f7f8;   /* sangat lembut, hampir putih */
  --mac-bg-elevated:    #ffffff;
  --mac-border:         #e8e8ed;
  --mac-border-strong:  #d1d1d6;
  --mac-text:           #1d1d1f;
  --mac-text-secondary: #6e6e73;
  --mac-text-tertiary:  #86868b;

  /* Accent */
  --mac-accent:         #0071e3;
  --mac-accent-hover:   #0077ed;
  --mac-accent-active:  #006edb;
  --mac-accent-soft:    rgba(0, 113, 227, 0.08);

  --mac-success:        #30d158;
  --mac-warning:        #ff9f0a;
  --mac-danger:         #ff453a;
  --mac-info:           #64d2ff;
  --mac-neutral:        #8e8e93;

  /* Elegant border radius */
  --mac-radius-xs:  6px;
  --mac-radius-sm:  8px;
  --mac-radius:     12px;
  --mac-radius-lg:  16px;
  --mac-radius-xl:  20px;
  --mac-radius-pill: 9999px;

  /* Soft floating shadows (lebih elegan & bertingkat) */
  --mac-shadow-xs:  0 1px 2px rgba(0, 0, 0, 0.03);
  --mac-shadow-sm:  0 2px 8px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.03);
  --mac-shadow-md:  0 8px 24px rgba(0, 0, 0, 0.06), 0 2px 6px rgba(0, 0, 0, 0.03);
  --mac-shadow-lg:  0 16px 40px rgba(0, 0, 0, 0.08), 0 4px 12px rgba(0, 0, 0, 0.04);
  --mac-shadow-xl:  0 24px 60px rgba(0, 0, 0, 0.10), 0 8px 20px rgba(0, 0, 0, 0.05);
  --mac-shadow-focus: 0 0 0 4px rgba(0, 113, 227, 0.16);

  --mac-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display",
              "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

html, body {
  background-color: var(--mac-bg);
  color: var(--mac-text);
  font-family: var(--mac-font) !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-size: 13px;
  line-height: 1.5;
}

h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: var(--mac-font) !important;
  font-weight: 600;
  color: var(--mac-text);
  letter-spacing: -0.015em;
}

/* ===================================================================
   2. LINK & TEXT
   =================================================================== */
a {
  color: var(--mac-accent);
}
a:hover, a:focus {
  color: var(--mac-accent-hover);
  text-decoration: none;
}

.text-primary, a.text-primary:hover, a.text-primary:focus { color: var(--mac-accent) !important; }
.text-success { color: #1e8e3e !important; }
.text-info    { color: #0071e3 !important; }
.text-warning { color: #b25000 !important; }
.text-danger  { color: #d93025 !important; }
.text-muted   { color: var(--mac-text-secondary) !important; }

a:focus,
.btn:focus, .btn:active:focus, .btn.active:focus,
input:focus, select:focus, textarea:focus,
.form-control:focus {
  outline: none !important;
  box-shadow: var(--mac-shadow-focus) !important;
}

/* ===================================================================
   3. BUTTONS — soft, rounded, clean
   =================================================================== */
.btn {
  font-family: var(--mac-font);
  font-weight: 500;
  border-radius: var(--mac-radius-sm);
  border: 1px solid transparent;
  box-shadow: none;
  transition: background-color .15s ease, box-shadow .15s ease, transform .05s ease;
}
.btn:active { transform: translateY(0.5px); }

.btn-default {
  color: var(--mac-text);
  background-color: #ffffff;
  border-color: var(--mac-border-strong);
  box-shadow: var(--mac-shadow-xs);
}
.btn-default:hover, .btn-default:focus {
  background-color: var(--mac-bg-subtle);
  border-color: var(--mac-border-strong);
  color: var(--mac-text);
}
.btn-default:active, .btn-default.active,
.open > .dropdown-toggle.btn-default {
  background-color: #ececef;
  border-color: var(--mac-border-strong);
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.06);
}

.btn-primary {
  color: #fff;
  background-color: var(--mac-accent);
  border-color: var(--mac-accent);
  box-shadow: var(--mac-shadow-xs);
}
.btn-primary:hover, .btn-primary:focus {
  background-color: var(--mac-accent-hover);
  border-color: var(--mac-accent-hover);
}
.btn-primary:active, .btn-primary.active,
.open > .dropdown-toggle.btn-primary {
  background-color: var(--mac-accent-active);
  border-color: var(--mac-accent-active);
}

.btn-success { background-color: var(--mac-success); border-color: var(--mac-success); }
.btn-success:hover, .btn-success:focus { background-color: #28b94d; border-color: #28b94d; }

.btn-info { background-color: #5ac8fa; border-color: #5ac8fa; color: #003a5c; }
.btn-info:hover, .btn-info:focus { background-color: #48b9ee; border-color: #48b9ee; }

.btn-warning { background-color: var(--mac-warning); border-color: var(--mac-warning); }
.btn-warning:hover, .btn-warning:focus { background-color: #e88f00; border-color: #e88f00; }

.btn-danger { background-color: var(--mac-danger); border-color: var(--mac-danger); }
.btn-danger:hover, .btn-danger:focus { background-color: #e6362c; border-color: #e6362c; }

.btn-link { color: var(--mac-accent); }
.btn-link:hover, .btn-link:focus { color: var(--mac-accent-hover); }

.btn-lg, .btn-group-lg > .btn { border-radius: var(--mac-radius-sm); }

/* ===================================================================
   4. NAVBAR — pure white + soft shadow
   =================================================================== */
.navbar {
  background-color: rgba(255, 255, 255, 0.88) !important;
  -webkit-backdrop-filter: saturate(180%) blur(16px);
  backdrop-filter: saturate(180%) blur(16px);
  border: none !important;
  box-shadow: var(--mac-shadow-sm);
  border-radius: 0;
}
.navbar-default {
  background-color: rgba(255, 255, 255, 0.88) !important;
  border-color: transparent !important;
}
.navbar-default .navbar-brand,
.navbar-default .navbar-nav > li > a,
.navbar a, .navbar li {
  color: var(--mac-text) !important;
}
.navbar-default .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > li > a:focus,
.navbar-default .navbar-nav > .active > a,
.navbar-default .navbar-nav > .active > a:hover,
.navbar-default .navbar-nav > .active > a:focus,
.navbar .open > a:hover {
  color: var(--mac-accent) !important;
  background-color: var(--mac-accent-soft) !important;
  border-radius: var(--mac-radius-sm);
}
.navbar-inverse {
  background-color: #1d1d1f !important;
  border-color: transparent !important;
  box-shadow: var(--mac-shadow-sm);
}
.navbar-inverse .navbar-brand,
.navbar-inverse .navbar-nav > li > a { color: #f5f5f7 !important; }

.navbar .input-group {
  background: var(--mac-bg-subtle) !important;
  border-radius: var(--mac-radius-pill);
}
.navbar .input-group .form-control.form-control,
.navbar .input-group .btn.btn {
  color: var(--mac-text) !important;
}

/* ===================================================================
   5. PANEL / CARD — pure white + floating shadow + elegant radius
   =================================================================== */
.panel {
  background-color: var(--mac-bg-elevated);
  border: none !important;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-sm);
}
.panel-heading {
  background-color: transparent;
  border-bottom: 1px solid var(--mac-border);
  border-top-left-radius: var(--mac-radius);
  border-top-right-radius: var(--mac-radius);
  font-weight: 600;
  padding: 14px 18px;
}
.panel-footer {
  background-color: var(--mac-bg-subtle);
  border-top: 1px solid var(--mac-border);
  border-bottom-left-radius: var(--mac-radius);
  border-bottom-right-radius: var(--mac-radius);
}
.panel-body { padding: 18px; }

.panel-default,
.panel-primary,
.panel-success,
.panel-info,
.panel-warning,
.panel-danger {
  border-color: transparent !important;
}
.panel-default > .panel-heading {
  background-color: transparent !important;
  color: var(--mac-text) !important;
  border-color: var(--mac-border) !important;
}
.panel-primary > .panel-heading {
  background-color: var(--mac-accent) !important;
  color: #fff !important;
  border-color: var(--mac-accent) !important;
}
.panel-success > .panel-heading { background-color: #eafcee !important; color: #1e8e3e !important; }
.panel-info    > .panel-heading { background-color: #e8f6ff !important; color: #0071e3 !important; }
.panel-warning > .panel-heading { background-color: #fff6e5 !important; color: #b25000 !important; }
.panel-danger  > .panel-heading { background-color: #fdeceb !important; color: #d93025 !important; }

/* welcome cards */
.bs-welcome-item {
  border: none !important;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-sm);
  background: #fff !important;
  overflow: hidden;
  transition: box-shadow .2s ease, transform .2s ease;
}
.bs-welcome-item:hover {
  box-shadow: var(--mac-shadow-md);
  transform: translateY(-2px);
}
.bs-welcome-item .bs-welcome-header {
  background: var(--mac-bg-subtle) !important;
  color: var(--mac-text) !important;
  border: none !important;
}

/* dashboard boxes */
.r-box-left, .r-box-right {
  border: none !important;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-sm);
  background-color: #fff !important;
}

/* sidebar */
.r-vbar-page .r-left,
.r-leftbar-top-page > .r-under .r-left {
  background-color: #fff !important;
  box-shadow: var(--mac-shadow-sm) !important;
  border-right: 1px solid var(--mac-border) !important;
}
.r-vbar-page .r-left .panel,
.r-leftbar-top-page > .r-under .r-left .panel {
  background-color: transparent !important;
  box-shadow: none !important;
  color: var(--mac-text-secondary) !important;
}
.r-vbar-page .r-left .panel .panel-heading,
.r-leftbar-top-page > .r-under .r-left .panel .panel-heading {
  background-color: transparent !important;
  color: var(--mac-text) !important;
  border-bottom-color: var(--mac-border) !important;
}
.r-left .r-menu [data-menu-link]:hover {
  color: var(--mac-accent) !important;
  background: var(--mac-accent-soft) !important;
  border-radius: var(--mac-radius-sm);
}
.r-left .r-menu li.active.active.active > [data-menu-link] {
  background: var(--mac-accent) !important;
  box-shadow: none !important;
  border-radius: var(--mac-radius-sm);
}

/* ===================================================================
   6. TABLE
   =================================================================== */
.table {
  background-color: #fff;
}
.table > thead > tr > th {
  border-bottom: 1px solid var(--mac-border-strong);
