  border-radius: var(--mac-radius-lg);
  box-shadow: var(--mac-shadow-xl);
}
.modal-header, .modal-footer {
  border-color: var(--mac-border);
}
.modal-header {
  border-top-left-radius: var(--mac-radius-lg);
  border-top-right-radius: var(--mac-radius-lg);
}
.modal-footer {
  border-bottom-left-radius: var(--mac-radius-lg);
  border-bottom-right-radius: var(--mac-radius-lg);
  background: var(--mac-bg-subtle);
}
.modal-backdrop.in { opacity: 0.32; background-color: #000; }

/* ===================================================================
   10. ALERT / LABEL / BADGE
   =================================================================== */
.alert {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-xs);
}
.alert-success { background-color: #eafcee; color: #1e8e3e; }
.alert-info    { background-color: #e8f6ff; color: #0071e3; }
.alert-warning { background-color: #fff6e5; color: #b25000; }
.alert-danger  { background-color: #fdeceb; color: #d93025; }

.label { border-radius: var(--mac-radius-sm); font-weight: 600; }
.label-primary { background-color: var(--mac-accent); }
.label-success { background-color: var(--mac-success); }
.label-info    { background-color: #5ac8fa; color: #003a5c; }
.label-warning { background-color: var(--mac-warning); }
.label-danger  { background-color: var(--mac-danger); }

.badge {
  background-color: var(--mac-neutral);
  border-radius: var(--mac-radius-pill);
}
.list-group-item.active > .badge,
