/*!
 * macOS Pure White Theme — Override Layer (Refined)
 * -----------------------------------------------------------------
 * Cara pakai: muat file ini SETELAH stylesheet Bootstrap/Ubuntu asli
 *
 *   <link rel="stylesheet" href="bootstrap-original.css">
 *   <link rel="stylesheet" href="macos-theme-override.css">
 *
 * Fokus: pure white + soft floating shadow + elegant radius
 * -----------------------------------------------------------------
 */

/* ===================================================================
   1. FONT & ROOT VARIABLES
   =================================================================== */
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap");

html,
body,
button,
input,
select,
textarea,
.navbar,
.table,
.form-control {
    font-family:
        "Inter",
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        sans-serif !important;
}

:root {
  /* Pure white palette */
  --mac-bg:             #ffffff;
  --mac-bg-subtle:      #f7f7f8;   /* sangat lembut, hampir putih */
  --mac-bg-elevated:    #ffffff;
  --mac-border:         #e8e8ed;
  --mac-border-strong:  #d1d1d6;
  --mac-text:           #1d1d1f;
  --mac-text-secondary: #6e6e73;
  --mac-text-tertiary:  #86868b;

  /* Accent */
  --mac-accent:         #0071e3;
  --mac-accent-hover:   #0077ed;
  --mac-accent-active:  #006edb;
  --mac-accent-soft:    rgba(0, 113, 227, 0.08);

  --mac-success:        #30d158;
  --mac-warning:        #ff9f0a;
  --mac-danger:         #ff453a;
  --mac-info:           #64d2ff;
  --mac-neutral:        #8e8e93;

  /* Elegant border radius */
  --mac-radius-xs:  6px;
  --mac-radius-sm:  8px;
  --mac-radius:     12px;
  --mac-radius-lg:  16px;
  --mac-radius-xl:  20px;
  --mac-radius-pill: 9999px;

  /* Soft floating shadows (lebih elegan & bertingkat) */
  --mac-shadow-xs:  0 1px 2px rgba(0, 0, 0, 0.03);
  --mac-shadow-sm:  0 2px 8px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.03);
  --mac-shadow-md:  0 8px 24px rgba(0, 0, 0, 0.06), 0 2px 6px rgba(0, 0, 0, 0.03);
  --mac-shadow-lg:  0 16px 40px rgba(0, 0, 0, 0.08), 0 4px 12px rgba(0, 0, 0, 0.04);
  --mac-shadow-xl:  0 24px 60px rgba(0, 0, 0, 0.10), 0 8px 20px rgba(0, 0, 0, 0.05);
  --mac-shadow-focus: 0 0 0 4px rgba(0, 113, 227, 0.16);

  --mac-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display",
              "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

html, body {
  background-color: var(--mac-bg);
  color: var(--mac-text);
  font-family: var(--mac-font) !important;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-size: 13px;
  line-height: 1.5;
}

h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: var(--mac-font) !important;
  font-weight: 600;
  color: var(--mac-text);
  letter-spacing: -0.015em;
}

/* ===================================================================
   2. LINK & TEXT
   =================================================================== */
a {
  color: var(--mac-accent);
}
a:hover, a:focus {
  color: var(--mac-accent-hover);
  text-decoration: none;
}

.text-primary, a.text-primary:hover, a.text-primary:focus { color: var(--mac-accent) !important; }
.text-success { color: #1e8e3e !important; }
.text-info    { color: #0071e3 !important; }
.text-warning { color: #b25000 !important; }
.text-danger  { color: #d93025 !important; }
.text-muted   { color: var(--mac-text-secondary) !important; }

a:focus,
.btn:focus, .btn:active:focus, .btn.active:focus,
input:focus, select:focus, textarea:focus,
.form-control:focus {
  outline: none !important;
  box-shadow: var(--mac-shadow-focus) !important;
}

/* ===================================================================
   3. BUTTONS — soft, rounded, clean
   =================================================================== */
.btn {
  font-family: var(--mac-font);
  font-weight: 500;
  border-radius: var(--mac-radius-sm);
  border: 1px solid transparent;
  box-shadow: none;
  transition: background-color .15s ease, box-shadow .15s ease, transform .05s ease;
}
.btn:active { transform: translateY(0.5px); }

.btn-default {
