.btn-link { color: var(--mac-accent); }
.btn-link:hover, .btn-link:focus { color: var(--mac-accent-hover); }

.btn-lg, .btn-group-lg > .btn { border-radius: var(--mac-radius-sm); }

/* ===================================================================
   4. NAVBAR — pure white + soft shadow
   =================================================================== */
.navbar {
  background-color: rgba(255, 255, 255, 0.88) !important;
  -webkit-backdrop-filter: saturate(180%) blur(16px);
  backdrop-filter: saturate(180%) blur(16px);
